from typing import List

def minCost(n: int, cost: List[List[int]]) -> int:
    # Dynamic programming table to store the minimum cost
    dp = [[0] * 3 for _ in range(n)]
    dp[0] = cost[0]

    for i in range(1, n):
        for j in range(3):
            # Calculate the minimum cost for painting house i with color j
            dp[i][j] = cost[i][j] + min(dp[i - 1][(j + 1) % 3], dp[i - 1][(j + 2) % 3])

    # Now, handle the mirrored conditions
    min_cost = float('inf')

    for first_color in range(3):
        for last_color in range(3):
            if first_color != last_color:
                total_cost = dp[n - 1][first_color] + cost[0][last_color]  # Correct the last house to consider valid color
                min_cost = min(min_cost, total_cost)

    return min_cost

from typing import List


def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    time_offline = [0] * numberOfUsers

    for event in sorted(events, key=lambda x: (int(x[1]), 0 if x[0] == "OFFLINE" else 1)):
        event_type, timestamp, *details = event
        timestamp = int(timestamp)

        if event_type == "OFFLINE":
            user_id = int(details[0])
            online_status[user_id] = False
            time_offline[user_id] = timestamp + 60
        elif event_type == "MESSAGE":
            # Process offline statuses before the message
            for user_id in range(numberOfUsers):
                if not online_status[user_id] and timestamp >= time_offline[user_id]:
                    online_status[user_id] = True

            mentions_string = details[0]
            if mentions_string == "ALL":
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif mentions_string == "HERE":
                for i in range(numberOfUsers):
                    if online_status[i]:
                        mentions[i] += 1
            else:
                mentioned_ids = mentions_string.split()
                for mention in mentioned_ids:
                    user_id = int(mention[2:])  # Get id<number>
                    mentions[user_id] += 1

    return mentions

